const entry = msg.payload;

msg.payload = {
    id:        entry.id,
    text:      entry.text             || "",
    timestamp: entry.timeCreated,
    author:    entry.loggedByFullName || "",
    labels:    entry.labels           || [],
    files: entry.files || []
};

return msg;

const entry = msg.payload;

const isLocation = entry.location === true;
let text = entry.content || "";

if (isLocation) {
    try {
        const geojson = JSON.parse(entry.content);
        const [lng, lat] = geojson.geometry.coordinates;
        const description = geojson.properties?.description || "";
        const mapsLink = "Klikk her for å åpne i Google Maps:\nhttps://www.google.com/maps?q=" + lat + "%2C" + lng;
        text = description ? description + "\n\n" + mapsLink : mapsLink;
        msg.geo = { lat, lng };
        msg.isLocation = true;
    } catch (e) {
        text = entry.content || "";
    }
}

msg.payload = {
    id: entry.id,
    text: text,
    timestamp: new Date(entry.createdAt).getTime(),
    author: entry.username || "",
    files: entry.files || [],
    labels: [],
    geo: msg.geo || null,
    isLocation: isLocation
};

return msg;

if (msg.mapImage) {
    const utils = global.get("utils");
    const entry = msg.payload;
    const connection_name = msg.metadata.connection_name;

    const key = utils.build_file_key(entry.id, connection_name, msg.mapImage.name);
    global.set("files." + key, msg.mapImage.buffer);

    const file = {
        name: msg.mapImage.name,
        type: msg.mapImage.type,
        size: msg.mapImage.buffer.length,
        context_key: key
    };

    entry.files = (entry.files || []).concat(file);
    delete msg.mapImage;
}

delete msg.geo;
delete msg.isLocation;

return msg;
